1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"strings"
12		"time"
13	)
14	
15	// 数据目录布局：
16	//
17	//	<dir>/state.json      全部业务数据（客户、用量、账单、封账状态）
18	//	<dir>/state.json.tmp  原子写入临时文件（保存后 rename 覆盖）
19	//
20	// 所有命令顺序运行，单次调用内完成“读入—修改—整体原子落盘”，
21	// 因此账单与封账状态在同一次保存中持久化，不会出现半写状态。
22	
23	const stateVersion = 1
24	
25	type customer struct {
26		ID     string `json:"id"`
27		Name   string `json:"name"`
28		Price  int64  `json:"price_fen"`        // 固定单价，非负整数分，创建后不可修改
29		PlanID string `json:"plan_id,omitempty"` // 绑定的阶梯计费方案标识；空表示固定单价客户，创建后不可变更
30	}
31	
32	// tier 是阶梯计费方案中的一档：Limit 为月累计数量上限（正整数），
33	// 仅最后一档无上限（Limit 为 0）；Price 为该档每单位价格（非负整数分）。
34	type tier struct {
35		Limit int64 `json:"limit"`     // 累计数量上限；0 表示无上限（仅最后一档）
36		Price int64 `json:"price_fen"` // 每单位价格，非负整数分，可升可降
37	}
38	
39	// plan 是按月累计用量的阶梯计费方案：标识唯一非空、名称非空、至少一档
40	// 有序阶梯；创建后不可修改。
41	type plan struct {
42		ID    string `json:"id"`
43		Name  string `json:"name"`
44		Tiers []tier `json:"tiers"` // 至少一档；有限上限严格递增，最后一档无上限
45	}
46	
47	type usageRecord struct {
48		ID         string `json:"id"`
49		CustomerID string `json:"customer_id"`
50		Time       string `json:"time"` // RFC3339，保留原始输入用于去重判定
51		Quantity   int64  `json:"quantity"`
52	}
53	
54	// lineSegment 是阶梯计费下一条用量记录落入某一档的分段：数量与小计；
55	// 该档单价由账单保存的方案规则按档位序号取得。
56	type lineSegment struct {
57		Tier     int   `json:"tier"`     // 档位序号（0 起，对应账单保存的方案规则）
58		Quantity int64 `json:"quantity"` // 落入本档的数量
59		Fee      int64 `json:"fee_fen"`  // 本分段小计（数量 × 该档单价）
60	}
61	
62	// tierTotal 是阶梯账单中某一档的合计数量与金额（与 PlanTiers 顺序对齐）。
63	type tierTotal struct {
64		Quantity int64 `json:"quantity"`
65		Fee      int64 `json:"fee_fen"`
66	}
67	
68	type billLine struct {
69		UsageID  string        `json:"usage_id"`
70		Time     string        `json:"time"`
71		Quantity int64         `json:"quantity"`
72		LineFee  int64         `json:"line_fee_fen"`
73		Segments []lineSegment `json:"segments,omitempty"` // 阶梯账单：本条用量的跨档分段
74	}
75	
76	type bill struct {
77		ID         string      `json:"id"`
78		CustomerID string      `json:"customer_id"`
79		Month      string      `json:"month"` // YYYY-MM（UTC）
80		Pricing    string      `json:"pricing,omitempty"`      // 计价类型：空或 fixed 为固定单价；tiered 为阶梯计费
81		PlanID     string      `json:"plan_id,omitempty"`      // 阶梯账单：方案标识
82		PlanName   string      `json:"plan_name,omitempty"`    // 阶梯账单：方案名称（快照）
83		PlanTiers  []tier      `json:"plan_tiers,omitempty"`   // 阶梯账单：完整方案规则（快照）
84		TierTotals []tierTotal `json:"tier_totals,omitempty"`  // 阶梯账单：各档实际数量与金额合计
85		TotalQty   int64       `json:"total_quantity"`
86		UnitPrice  int64       `json:"unit_price_fen"` // 固定单价账单的单价；阶梯账单恒为 0（不伪造统一单价）
87		TotalFee   int64       `json:"total_fee_fen"`
88		Lines      []billLine  `json:"lines"`
89		CreatedAt  string      `json:"created_at"`
90	}
91	
92	// adjustment 是对已结算账单的一次费用调整（正数补收、负数减免）。
93	// 记录一旦写入永不删除；撤销只是追加撤销信息，保留原记录。
94	type adjustment struct {
95		ID           string `json:"id"`
96		CustomerID   string `json:"customer_id"`
97		Month        string `json:"month"` // YYYY-MM（UTC），与所属账单一致
98		Amount       int64  `json:"amount_fen"`
99		Reason       string `json:"reason"`
100		Seq          int64  `json:"seq"` // 全局递增操作序号，决定历史展示顺序
101		CreatedAt    string `json:"created_at"`
102		Revoked      bool   `json:"revoked"`
103		RevokeReason string `json:"revoke_reason,omitempty"`
104		RevokeSeq    int64  `json:"revoke_seq,omitempty"`
105		RevokedAt    string `json:"revoked_at,omitempty"`
106	}
107	
108	// paymentAllocation 是一笔收款在某个已结算月份上的分配（正整数分）。
109	type paymentAllocation struct {
110		Month  string `json:"month"`      // YYYY-MM（UTC），须已有账单
111		Amount int64  `json:"amount_fen"` // 正整数分
112	}
113	
114	// payment 是一笔实收登记：同一客户的一笔汇款（总额 Total 分）按分配列表
115	// 计入一个或多个已结算月份；单账单收款视为只有一项分配的汇款。
116	// 记录一旦写入永不删除；撤销只是追加撤销信息，整笔撤销全部分配并保留
117	// 原记录，撤销后该笔不再计入实收，也不会因重放而恢复。
118	type payment struct {
119		ID           string              `json:"id"`
120		CustomerID   string              `json:"customer_id"`
121		Total        int64               `json:"total_fen"` // 收款总额，正整数分，等于分配合计
122		Note         string              `json:"note"`
123		Allocations  []paymentAllocation `json:"allocations"` // 至少一项，月份不重复，按月份升序保存
124		Seq          int64               `json:"seq"`         // 全局递增操作序号，决定历史展示顺序
125		CreatedAt    string              `json:"created_at"`
126		Revoked      bool                `json:"revoked"`
127		RevokeReason string              `json:"revoke_reason,omitempty"`
128		RevokeSeq    int64               `json:"revoke_seq,omitempty"`
129		RevokedAt    string              `json:"revoked_at,omitempty"`
130	}
131	
132	// UnmarshalJSON 兼容旧版单账单收款格式（month + amount_fen，无 allocations）：
133	// 读入时归一化为一项分配，之后一律按新格式写回。
134	func (p *payment) UnmarshalJSON(data []byte) error {
135		type plain payment // 去掉方法，避免递归
136		var raw struct {
137			plain
138			Month  string `json:"month"`      // 旧格式：所属账单月份
139			Amount int64  `json:"amount_fen"` // 旧格式：收款金额
140		}
141		if err := json.Unmarshal(data, &raw); err != nil {
142			return err
143		}
144		*p = payment(raw.plain)
145		if len(p.Allocations) == 0 && raw.Month != "" {
146			p.Allocations = []paymentAllocation{{Month: raw.Month, Amount: raw.Amount}}
147			p.Total = raw.Amount
148		}
149		return nil
150	}
151	
152	// amountFor 返回该收款在指定月份的分配金额；无分配时为 0。
153	func (p *payment) amountFor(month string) int64 {
154		for _, al := range p.Allocations {
155			if al.Month == month {
156				return al.Amount
157			}
158		}
159		return 0
160	}
161	
162	// correction 是对一笔未撤销收款的分配更正：客户、总额、备注、原账单及
163	// 应付不变，仅把该笔收款当前生效的分配整体替换为完整新分配。记录一旦写入
164	// 永不删除；首次登记内容永久保留，bill pay / bill remit 仍按原始分配判重，
165	// 更正不影响收款身份。可连续更正，每次以当时最新分配为起点。
166	type correction struct {
167		ID          string              `json:"id"`
168		PaymentID   string              `json:"payment_id"` // 目标收款标识
169		Reason      string              `json:"reason"`
170		Allocations []paymentAllocation `json:"allocations"` // 完整新分配，至少一项，月份不重复，按月份升序保存
171		Seq         int64               `json:"seq"`         // 全局递增操作序号，与调整/收款及其撤销共用
172		CreatedAt   string              `json:"created_at"`
173	}
174	
175	type state struct {
176		Version     int                     `json:"version"`
177		Customers   map[string]*customer    `json:"customers"`
178		Plans       map[string]*plan        `json:"plans"`       // 全局唯一方案标识 -> 阶梯计费方案
179		Usage       map[string]*usageRecord `json:"usage"`       // 全局唯一用量标识 -> 记录
180		Bills       map[string]*bill        `json:"bills"`       // 客户 + "|" + 月份 -> 账单
181		Adjustments map[string]*adjustment  `json:"adjustments"` // 全局唯一调整标识 -> 记录
182		Payments    map[string]*payment     `json:"payments"`    // 全局唯一收款标识 -> 记录（与调整标识相互独立，可同名）
183		Corrections map[string]*correction  `json:"corrections"` // 全局唯一更正标识 -> 记录（与收款、调整标识相互独立，可同名）
184		NextSeq     int64                   `json:"next_seq"`    // 已分配的最大操作序号（调整/收款/更正及其撤销共用）
185		path        string                  `json:"-"`
186	}
187	
188	// loadStore 读取数据目录；目录不存在时按需创建并视为空库。
189	// 已存在但损坏或不可读取的数据一律报错，绝不当作空库覆盖。
190	func loadStore(dir string) (*state, error) {
191		p := filepath.Join(dir, "state.json")
192		data, err := os.ReadFile(p)
193		if err != nil {
194			if errors.Is(err, os.ErrNotExist) {
195				if mkErr := os.MkdirAll(dir, 0o755); mkErr != nil {
196					return nil, fmt.Errorf("无法创建数据目录 %s: %w", dir, mkErr)
197				}
198				return newState(p), nil
199			}
200			return nil, fmt.Errorf("数据文件不可读取 %s: %w", p, err)
201		}
202	
203		var s state
204		dec := json.NewDecoder(bytes.NewReader(data))
205		if err := dec.Decode(&s); err != nil {
206			return nil, fmt.Errorf("数据文件已损坏（不是有效的 JSON）%s: %w", p, err)
207		}
208		// 拒绝尾部多余内容，避免静默吞掉异常数据。
209		if dec.More() {
210			return nil, fmt.Errorf("数据文件已损坏（JSON 之后存在多余内容）: %s", p)
211		}
212		if err := s.validate(); err != nil {
213			return nil, fmt.Errorf("数据文件已损坏: %w", err)
214		}
215		// 旧版本数据文件没有 plans/adjustments/payments/corrections/next_seq 字段：
216		// 视为零方案、零调整、零实收、零更正。
217		if s.Plans == nil {
218			s.Plans = map[string]*plan{}
219		}
220		if s.Adjustments == nil {
221			s.Adjustments = map[string]*adjustment{}
222		}
223		if s.Payments == nil {
224			s.Payments = map[string]*payment{}
225		}
226		if s.Corrections == nil {
227			s.Corrections = map[string]*correction{}
228		}
229		s.path = p
230		return &s, nil
231	}
232	
233	func newState(p string) *state {
234		return &state{
235			Version:     stateVersion,
236			Customers:   map[string]*customer{},
237			Plans:       map[string]*plan{},
238			Usage:       map[string]*usageRecord{},
239			Bills:       map[string]*bill{},
240			Adjustments: map[string]*adjustment{},
241			Payments:    map[string]*payment{},
242			Corrections: map[string]*correction{},
243			path:        p,
244		}
245	}
246	
247	// validate 对读入的库做一致性检查，任何异常都按损坏处理。
248	func (s *state) validate() error {
249		if s.Version != stateVersion {
250			return fmt.Errorf("不支持的数据版本 %d（仅支持 %d）", s.Version, stateVersion)
251		}
252		if s.Customers == nil || s.Usage == nil || s.Bills == nil {
253			return errors.New("缺少必要的数据节")
254		}
255		for id, p := range s.Plans {
256			if p == nil {
257				return fmt.Errorf("方案 %q 的数据为空", id)
258			}
259			if p.ID != id {
260				return fmt.Errorf("方案标识不一致: 键 %q / 记录 %q", id, p.ID)
261			}
262			if err := validatePlanRules(p); err != nil {
263				return err
264			}
265		}
266		for id, c := range s.Customers {
267			if c == nil {
268				return fmt.Errorf("客户 %q 的数据为空", id)
269			}
270			if c.ID != id {
271				return fmt.Errorf("客户标识不一致: 键 %q / 记录 %q", id, c.ID)
272			}
273			if c.ID == "" || c.Name == "" {
274				return fmt.Errorf("客户 %q 的标识或名称为空", id)
275			}
276			if c.Price < 0 {
277				return fmt.Errorf("客户 %q 单价为负", id)
278			}
279			if c.PlanID != "" {
280				if _, ok := s.Plans[c.PlanID]; !ok {
281					return fmt.Errorf("客户 %q 绑定了不存在的方案 %q", id, c.PlanID)
282				}
283			}
284		}
285		for id, u := range s.Usage {
286			if u == nil {
287				return fmt.Errorf("用量 %q 的数据为空", id)
288			}
289			if u.ID != id {
290				return fmt.Errorf("用量标识不一致: 键 %q / 记录 %q", id, u.ID)
291			}
292			if u.ID == "" {
293				return errors.New("存在空的用量标识")
294			}
295			if _, ok := s.Customers[u.CustomerID]; !ok {
296				return fmt.Errorf("用量 %q 引用了不存在的客户 %q", u.ID, u.CustomerID)
297			}
298			if u.Quantity <= 0 {
299				return fmt.Errorf("用量 %q 的数量非正", u.ID)
300			}
301			if _, err := time.Parse(time.RFC3339, u.Time); err != nil {
302				return fmt.Errorf("用量 %q 的时间不是 RFC3339: %w", u.ID, err)
303			}
304		}
305		for key, b := range s.Bills {
306			if b == nil {
307				return fmt.Errorf("账单 %q 的数据为空", key)
308			}
309			if billKey(b.CustomerID, b.Month) != key {
310				return fmt.Errorf("账单键不一致: 键 %q / 客户月份 %s|%s", key, b.CustomerID, b.Month)
311			}
312			if _, ok := s.Customers[b.CustomerID]; !ok {
313				return fmt.Errorf("账单 %q 引用了不存在的客户 %q", key, b.CustomerID)
314			}
315			if !validMonth(b.Month) {
316				return fmt.Errorf("账单 %q 的月份无效", key)
317			}
318			if len(b.Lines) == 0 {
319				return fmt.Errorf("账单 %q 没有明细", key)
320			}
321			var qty, fee int64
322			for _, ln := range b.Lines {
323				u, ok := s.Usage[ln.UsageID]
324				if !ok {
325					return fmt.Errorf("账单 %q 引用了不存在的用量 %q", key, ln.UsageID)
326				}
327				if u.CustomerID != b.CustomerID || u.Time != ln.Time || u.Quantity != ln.Quantity {
328					return fmt.Errorf("账单 %q 的明细 %q 与用量记录不一致", key, ln.UsageID)
329				}
330				if !inMonth(u.Time, b.Month) {
331					return fmt.Errorf("账单 %q 的明细 %q 不在账期内", key, ln.UsageID)
332				}
333				var err error
334				qty, err = add64(qty, ln.Quantity)
335				if err != nil {
336					return fmt.Errorf("账单 %q 汇总数量溢出", key)
337				}
338				fee, err = add64(fee, ln.LineFee)
339				if err != nil {
340					return fmt.Errorf("账单 %q 汇总金额溢出", key)
341				}
342			}
343			if qty != b.TotalQty {
344				return fmt.Errorf("账单 %q 总数量与明细不符", key)
345			}
346			if fee != b.TotalFee {
347				return fmt.Errorf("账单 %q 总金额与明细不符", key)
348			}
349			c := s.Customers[b.CustomerID]
350			switch b.Pricing {
351			case "", "fixed":
352				// 固定单价账单：每条小计必须等于 数量×客户固定单价，且不得
353				// 携带阶梯方案信息或分段。
354				if b.PlanID != "" || b.PlanName != "" || len(b.PlanTiers) > 0 || len(b.TierTotals) > 0 {
355					return fmt.Errorf("账单 %q 是固定单价账单但携带阶梯方案信息", key)
356				}
357				for _, ln := range b.Lines {
358					if len(ln.Segments) > 0 {
359						return fmt.Errorf("账单 %q 的明细 %q 携带阶梯分段", key, ln.UsageID)
360					}
361					lf, err := mul64(ln.Quantity, c.Price)
362					if err != nil {
363						return fmt.Errorf("账单 %q 明细 %q 小计溢出", key, ln.UsageID)
364					}
365					if lf != ln.LineFee {
366						return fmt.Errorf("账单 %q 明细 %q 小计与数量×单价不符", key, ln.UsageID)
367					}
368				}
369				if b.UnitPrice != c.Price {
370					return fmt.Errorf("账单 %q 单价与客户固定单价不符", key)
371				}
372			case "tiered":
373				if err := s.validateTieredBill(key, b, c); err != nil {
374					return err
375				}
376			default:
377				return fmt.Errorf("账单 %q 的计价类型 %q 未知", key, b.Pricing)
378			}
379			// 封账期内不得存在游离于账单之外的用量（封账后新增被禁止，
380			// 而已入账记录理应全部在明细中）。
381			for _, u := range s.Usage {
382				if u.CustomerID == b.CustomerID && inMonth(u.Time, b.Month) {
383					found := false
384					for _, ln := range b.Lines {
385						if ln.UsageID == u.ID {
386							found = true
387							break
388						}
389					}
390					if !found {
391						return fmt.Errorf("客户 %s 的 %s 已封账，但用量 %q 未计入账单", b.CustomerID, b.Month, u.ID)
392					}
393				}
394			}
395		}
396	
397		// 调整与收款记录：标识、内容、引用与序号都必须自洽。
398		// 调整与收款共用同一个全局操作序号池；两者标识命名空间相互独立，
399		// 允许同名，各自判重与撤销。
400		if s.NextSeq < 0 {
401			return fmt.Errorf("操作序号计数器为负: %d", s.NextSeq)
402		}
403		seenSeq := make(map[int64]string) // 全局操作序号（登记与撤销共用同一池）-> 来源描述
404		for id, a := range s.Adjustments {
405			if a == nil {
406				return fmt.Errorf("调整 %q 的数据为空", id)
407			}
408			if a.ID != id {
409				return fmt.Errorf("调整标识不一致: 键 %q / 记录 %q", id, a.ID)
410			}
411			if a.ID == "" {
412				return errors.New("存在空的调整标识")
413			}
414			if a.Amount == 0 {
415				return fmt.Errorf("调整 %q 的金额为零", id)
416			}
417			if strings.TrimSpace(a.Reason) == "" {
418				return fmt.Errorf("调整 %q 的原因为空", id)
419			}
420			if !validMonth(a.Month) {
421				return fmt.Errorf("调整 %q 的月份无效", id)
422			}
423			if _, ok := s.Customers[a.CustomerID]; !ok {
424				return fmt.Errorf("调整 %q 引用了不存在的客户 %q", id, a.CustomerID)
425			}
426			if _, ok := s.Bills[billKey(a.CustomerID, a.Month)]; !ok {
427				return fmt.Errorf("调整 %q 引用了不存在的账单（客户 %s 月份 %s）", id, a.CustomerID, a.Month)
428			}
429			if a.Seq < 1 || a.Seq > s.NextSeq {
430				return fmt.Errorf("调整 %q 的操作序号越界", id)
431			}
432			if prev, dup := seenSeq[a.Seq]; dup {
433				return fmt.Errorf("调整 %q 与 %q 的操作序号重复", id, prev)
434			}
435			seenSeq[a.Seq] = "调整 " + id
436			if a.Revoked {
437				if strings.TrimSpace(a.RevokeReason) == "" {
438					return fmt.Errorf("调整 %q 已撤销但撤销原因为空", id)
439				}
440				if a.RevokeSeq <= a.Seq || a.RevokeSeq > s.NextSeq {
441					return fmt.Errorf("调整 %q 的撤销序号越界", id)
442				}
443				if prev, dup := seenSeq[a.RevokeSeq]; dup {
444					return fmt.Errorf("撤销调整 %q 与 %q 的操作序号重复", id, prev)
445				}
446				seenSeq[a.RevokeSeq] = "撤销调整 " + id
447			} else if a.RevokeReason != "" || a.RevokeSeq != 0 {
448				return fmt.Errorf("调整 %q 未撤销但存在撤销信息", id)
449			}
450		}
451		for id, p := range s.Payments {
452			if p == nil {
453				return fmt.Errorf("收款 %q 的数据为空", id)
454			}
455			if p.ID != id {
456				return fmt.Errorf("收款标识不一致: 键 %q / 记录 %q", id, p.ID)
457			}
458			if p.ID == "" {
459				return errors.New("存在空的收款标识")
460			}
461			if p.Total <= 0 {
462				return fmt.Errorf("收款 %q 的总额不是正整数", id)
463			}
464			if strings.TrimSpace(p.Note) == "" {
465				return fmt.Errorf("收款 %q 的备注为空", id)
466			}
467			if _, ok := s.Customers[p.CustomerID]; !ok {
468				return fmt.Errorf("收款 %q 引用了不存在的客户 %q", id, p.CustomerID)
469			}
470			if len(p.Allocations) == 0 {
471				return fmt.Errorf("收款 %q 没有分配", id)
472			}
473			seenMonths := make(map[string]bool)
474			var sum int64
475			for _, al := range p.Allocations {
476				if !validMonth(al.Month) {
477					return fmt.Errorf("收款 %q 的分配月份 %q 无效", id, al.Month)
478				}
479				if seenMonths[al.Month] {
480					return fmt.Errorf("收款 %q 的分配月份 %s 重复", id, al.Month)
481				}
482				seenMonths[al.Month] = true
483				if al.Amount <= 0 {
484					return fmt.Errorf("收款 %q 在 %s 的分配金额不是正整数", id, al.Month)
485				}
486				if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
487					return fmt.Errorf("收款 %q 的分配引用了不存在的账单（客户 %s 月份 %s）", id, p.CustomerID, al.Month)
488				}
489				var err error
490				sum, err = add64(sum, al.Amount)
491				if err != nil {
492					return fmt.Errorf("收款 %q 的分配金额汇总溢出: %w", id, err)
493				}
494			}
495			if sum != p.Total {
496				return fmt.Errorf("收款 %q 的分配合计 %d 分与总额 %d 分不一致", id, sum, p.Total)
497			}
498			if p.Seq < 1 || p.Seq > s.NextSeq {
499				return fmt.Errorf("收款 %q 的操作序号越界", id)
500			}
501			if prev, dup := seenSeq[p.Seq]; dup {
502				return fmt.Errorf("收款 %q 与 %q 的操作序号重复", id, prev)
503			}
504			seenSeq[p.Seq] = "收款 " + id
505			if p.Revoked {
506				if strings.TrimSpace(p.RevokeReason) == "" {
507					return fmt.Errorf("收款 %q 已撤销但撤销原因为空", id)
508				}
509				if p.RevokeSeq <= p.Seq || p.RevokeSeq > s.NextSeq {
510					return fmt.Errorf("收款 %q 的撤销序号越界", id)
511				}
512				if prev, dup := seenSeq[p.RevokeSeq]; dup {
513					return fmt.Errorf("撤销收款 %q 与 %q 的操作序号重复", id, prev)
514				}
515				seenSeq[p.RevokeSeq] = "撤销收款 " + id
516			} else if p.RevokeReason != "" || p.RevokeSeq != 0 {
517				return fmt.Errorf("收款 %q 未撤销但存在撤销信息", id)
518			}
519		}
520		// 分配更正记录：标识、目标收款、原因、新分配与序号都必须自洽。
521		// 更正标识与收款、调整标识命名空间相互独立，允许同名。
522		for id, c := range s.Corrections {
523			if c == nil {
524				return fmt.Errorf("更正 %q 的数据为空", id)
525			}
526			if c.ID != id {
527				return fmt.Errorf("更正标识不一致: 键 %q / 记录 %q", id, c.ID)
528			}
529			if c.ID == "" {
530				return errors.New("存在空的更正标识")
531			}
532			p, ok := s.Payments[c.PaymentID]
533			if !ok {
534				return fmt.Errorf("更正 %q 引用了不存在的收款 %q", id, c.PaymentID)
535			}
536			if strings.TrimSpace(c.Reason) == "" {
537				return fmt.Errorf("更正 %q 的原因为空", id)
538			}
539			if len(c.Allocations) == 0 {
540				return fmt.Errorf("更正 %q 没有新分配", id)
541			}
542			seenMonths := make(map[string]bool)
543			var sum int64
544			for _, al := range c.Allocations {
545				if !validMonth(al.Month) {
546					return fmt.Errorf("更正 %q 的分配月份 %q 无效", id, al.Month)
547				}
548				if seenMonths[al.Month] {
549					return fmt.Errorf("更正 %q 的分配月份 %s 重复", id, al.Month)
550				}
551				seenMonths[al.Month] = true
552				if al.Amount <= 0 {
553					return fmt.Errorf("更正 %q 在 %s 的分配金额不是正整数", id, al.Month)
554				}
555				if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
556					return fmt.Errorf("更正 %q 的分配引用了不存在的账单（客户 %s 月份 %s）", id, p.CustomerID, al.Month)
557				}
558				var err error
559				sum, err = add64(sum, al.Amount)
560				if err != nil {
561					return fmt.Errorf("更正 %q 的分配金额汇总溢出: %w", id, err)
562				}
563			}
564			if sum != p.Total {
565				return fmt.Errorf("更正 %q 的分配合计 %d 分与关联收款 %q 的总额 %d 分不一致", id, sum, c.PaymentID, p.Total)
566			}
567			if c.Seq <= p.Seq || c.Seq > s.NextSeq {
568				return fmt.Errorf("更正 %q 的操作序号越界", id)
569			}
570			if p.Revoked && c.Seq > p.RevokeSeq {
571				return fmt.Errorf("更正 %q 的操作序号晚于关联收款 %q 的撤销序号", id, c.PaymentID)
572			}
573			if prev, dup := seenSeq[c.Seq]; dup {
574				return fmt.Errorf("更正 %q 与 %q 的操作序号重复", id, prev)
575			}
576			seenSeq[c.Seq] = "更正 " + id
577		}
578		// 每张账单：当前应付（原总金额 + 全部未撤销调整净额）必须介于
579		// 0 与有符号 64 位最大值之间；实收（全部未撤销收款按最新分配在该月
580		// 计入之和）必须满足 0 ≤ 实收 ≤ 当前应付。越界说明金额与记录不一致。
581		for key, b := range s.Bills {
582			_, payable, err := billTotals(b, adjustmentsFor(s, b.CustomerID, b.Month))
583			if err != nil {
584				return fmt.Errorf("账单 %q 的调整金额与记录不一致: %w", key, err)
585			}
586			received, err := paymentReceived(s, b.CustomerID, b.Month)
587			if err != nil {
588				return fmt.Errorf("账单 %q 的收款金额与记录不一致: %w", key, err)
589			}
590			if received > payable {
591				return fmt.Errorf("账单 %q 的实收 %d 分超过当前应付 %d 分", key, received, payable)
592			}
593		}
594		return nil
595	}
596	
597	// validatePlanRules 校验阶梯方案的标识、名称与阶梯规则本身自洽：
598	// 至少一档，有限上限为严格递增的正整数，最后一档无上限，单价非负。
599	func validatePlanRules(p *plan) error {
600		if p.ID == "" || p.Name == "" {
601			return fmt.Errorf("方案 %q 的标识或名称为空", p.ID)
602		}
603		if len(p.Tiers) == 0 {
604			return fmt.Errorf("方案 %q 至少需要一档阶梯", p.ID)
605		}
606		prev := int64(0)
607		for i, t := range p.Tiers {
608			if t.Price < 0 {
609				return fmt.Errorf("方案 %q 第 %d 档单价为负", p.ID, i+1)
610			}
611			if i == len(p.Tiers)-1 {
612				if t.Limit != 0 {
613					return fmt.Errorf("方案 %q 最后一档必须无上限", p.ID)
614				}
615			} else {
616				if t.Limit <= 0 {
617					return fmt.Errorf("方案 %q 第 %d 档上限必须是正整数", p.ID, i+1)
618				}
619				if t.Limit <= prev {
620					return fmt.Errorf("方案 %q 的有限上限必须严格递增", p.ID)
621				}
622				prev = t.Limit
623			}
624		}
625		return nil
626	}
627	
628	// tiersEqual 判定两份阶梯规则完全相同。
629	func tiersEqual(a, b []tier) bool {
630		if len(a) != len(b) {
631			return false
632		}
633		for i := range a {
634			if a[i] != b[i] {
635				return false
636			}
637		}
638		return true
639	}
640	
641	// segmentsEqual 判定两份分段列表完全相同。
642	func segmentsEqual(a, b []lineSegment) bool {
643		if len(a) != len(b) {
644			return false
645		}
646		for i := range a {
647			if a[i] != b[i] {
648				return false
649			}
650		}
651		return true
652	}
653	
654	// sortedByInstant 判定用量记录是否按（解析后的时间点升序、同一时间按
655	// 标识字典序）排列，即阶梯计价的计价顺序。
656	func sortedByInstant(recs []*usageRecord) bool {
657		for i := 1; i < len(recs); i++ {
658			ti, _ := time.Parse(time.RFC3339, recs[i-1].Time)
659			tj, _ := time.Parse(time.RFC3339, recs[i].Time)
660			ui, uj := ti.UTC(), tj.UTC()
661			if uj.Before(ui) || (uj.Equal(ui) && recs[i].ID <= recs[i-1].ID) {
662				return false
663			}
664		}
665		return true
666	}
667	
668	// validateTieredBill 校验阶梯账单：方案引用有效、快照与方案一致、客户绑定
669	// 未变更，并按保存的方案规则从零累计重放计价，逐条比对分段、小计、各档
670	// 合计与总金额；任何不符都视为数据损坏。
671	func (s *state) validateTieredBill(key string, b *bill, c *customer) error {
672		if b.PlanID == "" {
673			return fmt.Errorf("账单 %q 缺少方案标识", key)
674		}
675		p, ok := s.Plans[b.PlanID]
676		if !ok {
677			return fmt.Errorf("账单 %q 引用了不存在的方案 %q", key, b.PlanID)
678		}
679		if b.PlanName != p.Name {
680			return fmt.Errorf("账单 %q 的方案名称快照与方案 %q 不符", key, b.PlanID)
681		}
682		if !tiersEqual(b.PlanTiers, p.Tiers) {
683			return fmt.Errorf("账单 %q 的方案规则快照与方案 %q 不符", key, b.PlanID)
684		}
685		if c.PlanID != b.PlanID {
686			return fmt.Errorf("账单 %q 的方案 %q 与客户当前绑定 %q 不一致", key, b.PlanID, c.PlanID)
687		}
688		if b.UnitPrice != 0 {
689			return fmt.Errorf("账单 %q 是阶梯账单但保存了统一单价", key)
690		}
691		if len(b.TierTotals) != len(p.Tiers) {
692			return fmt.Errorf("账单 %q 的分档合计档数与方案规则不符", key)
693		}
694		// 明细必须按计价顺序排列（前面已逐条核验与用量记录一致）。
695		recs := make([]*usageRecord, len(b.Lines))
696		for i, ln := range b.Lines {
697			recs[i] = s.Usage[ln.UsageID]
698		}
699		if !sortedByInstant(recs) {
700			return fmt.Errorf("账单 %q 的明细未按计价顺序（时间点升序、同一时间按标识字典序）排列", key)
701		}
702		priced, err := tieredPrice(p.Tiers, recs)
703		if err != nil {
704			return fmt.Errorf("账单 %q 按方案规则计价失败: %w", key, err)
705		}
706		for i, ln := range b.Lines {
707			if !segmentsEqual(ln.Segments, priced.lines[i].segments) {
708				return fmt.Errorf("账单 %q 的明细 %q 分段与计价规则不符", key, ln.UsageID)
709			}
710			if ln.LineFee != priced.lines[i].fee {
711				return fmt.Errorf("账单 %q 的明细 %q 小计与计价规则不符", key, ln.UsageID)
712			}
713		}
714		for i, tt := range b.TierTotals {
715			if tt.Quantity != priced.tierQty[i] || tt.Fee != priced.tierFee[i] {
716				return fmt.Errorf("账单 %q 的第 %d 档合计与计价规则不符", key, i+1)
717			}
718		}
719		if b.TotalFee != priced.totalFee {
720			return fmt.Errorf("账单 %q 总金额与计价规则不符", key)
721		}
722		return nil
723	}
724	
725	// save 整体原子落盘：先写临时文件并同步，再 rename 覆盖。
726	// 只有完整保存成功后调用方才会向用户报告成功。
727	func (s *state) save() error {
728		if err := s.validate(); err != nil {
729			return fmt.Errorf("拒绝写入不一致的数据: %w", err)
730		}
731		data, err := json.MarshalIndent(s, "", "  ")
732		if err != nil {
733			return fmt.Errorf("序列化数据失败: %w", err)
734		}
735		data = append(data, '\n')
736	
737		tmp := s.path + ".tmp"
738		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
739		if err != nil {
740			return fmt.Errorf("写入临时数据文件失败: %w", err)
741		}
742		if _, err := f.Write(data); err != nil {
743			f.Close()
744			os.Remove(tmp)
745			return fmt.Errorf("写入临时数据文件失败: %w", err)
746		}
747		if err := f.Sync(); err != nil {
748			f.Close()
749			os.Remove(tmp)
750			return fmt.Errorf("同步数据文件失败: %w", err)
751		}
752		if err := f.Close(); err != nil {
753			os.Remove(tmp)
754			return fmt.Errorf("关闭数据文件失败: %w", err)
755		}
756		if err := os.Rename(tmp, s.path); err != nil {
757			os.Remove(tmp)
758			return fmt.Errorf("替换数据文件失败: %w", err)
759		}
760		if dir, err := os.Open(filepath.Dir(s.path)); err == nil {
761			dir.Sync()
762			dir.Close()
763		}
764		return nil
765	}
766	
767	func billKey(customerID, month string) string {
768		return customerID + "|" + month
769	}
770	
771	// sealed 报告某客户的指定月份是否已封账。
772	func (s *state) sealed(customerID, month string) bool {
773		_, ok := s.Bills[billKey(customerID, month)]
774		return ok
775	}
776	
777	// adjustmentsFor 返回某客户某月账单的全部调整，按操作序号升序。
778	func adjustmentsFor(s *state, customerID, month string) []*adjustment {
779		var list []*adjustment
780		for _, a := range s.Adjustments {
781			if a.CustomerID == customerID && a.Month == month {
782				list = append(list, a)
783			}
784		}
785		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
786		return list
787	}
788	
789	// correctionsFor 返回某收款的全部分配更正，按操作序号升序。
790	func correctionsFor(s *state, paymentID string) []*correction {
791		var list []*correction
792		for _, c := range s.Corrections {
793			if c.PaymentID == paymentID {
794				list = append(list, c)
795			}
796		}
797		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
798		return list
799	}
800	
801	// currentAllocations 返回一笔收款当前生效的分配：无更正时为首次登记的
802	// 原始分配，否则为序号最大（最新）的更正的分配。
803	func currentAllocations(s *state, p *payment) []paymentAllocation {
804		var latest *correction
805		for _, c := range s.Corrections {
806			if c.PaymentID == p.ID && (latest == nil || c.Seq > latest.Seq) {
807				latest = c
808			}
809		}
810		if latest != nil {
811			return latest.Allocations
812		}
813		return p.Allocations
814	}
815	
816	// allocAmountFor 返回分配列表中指定月份的金额；无该月分配时为 0。
817	func allocAmountFor(allocs []paymentAllocation, month string) int64 {
818		for _, al := range allocs {
819			if al.Month == month {
820				return al.Amount
821			}
822		}
823		return 0
824	}
825	
826	// paymentsEverFor 返回历史上曾涉及某客户某月账单的全部收款（首次登记
827	// 分配或任一次更正的新分配涉及该月，即使后来被更正移出），按操作序号升序。
828	func paymentsEverFor(s *state, customerID, month string) []*payment {
829		var list []*payment
830		for _, p := range s.Payments {
831			if p.CustomerID != customerID {
832				continue
833			}
834			involved := p.amountFor(month) > 0
835			if !involved {
836				for _, c := range s.Corrections {
837					if c.PaymentID == p.ID && allocAmountFor(c.Allocations, month) > 0 {
838						involved = true
839						break
840					}
841				}
842			}
843			if involved {
844				list = append(list, p)
845			}
846		}
847		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
848		return list
849	}
850	
851	// paymentReceived 返回全部未撤销收款按最新分配在指定月份计入的实收之和。
852	// 各笔分配均为正整数，用非负 64 位加法累加，溢出时返回错误。
853	func paymentReceived(s *state, customerID, month string) (int64, error) {
854		var received int64
855		for _, p := range s.Payments {
856			if p.CustomerID != customerID || p.Revoked {
857				continue
858			}
859			amt := allocAmountFor(currentAllocations(s, p), month)
860			if amt <= 0 {
861				continue
862			}
863			var err error
864			received, err = add64(received, amt)
865			if err != nil {
866				return 0, err
867			}
868		}
869		return received, nil
870	}
871	
872	// errPayableOutOfRange 表示当前应付越出 [0, 有符号 64 位最大值]。
873	var errPayableOutOfRange = errors.New("当前应付越界（须介于 0 与有符号 64 位最大值之间）")
874	
875	// billTotals 计算全部未撤销调整的净额与当前应付（原总金额 + 净额）。
876	// 净额按 128 位精确求和（与顺序无关），再校验应付落在
877	// [0, 有符号 64 位最大值] 内，全程整数运算。
878	func billTotals(b *bill, adjs []*adjustment) (net, payable int64, err error) {
879		var amounts []int64
880		for _, a := range adjs {
881			if !a.Revoked {
882				amounts = append(amounts, a.Amount)
883			}
884		}
885		net, err = sumSigned64(amounts...)
886		if err != nil {
887			return 0, 0, err
888		}
889		payable, err = addSigned64(b.TotalFee, net)
890		if err != nil {
891			return 0, 0, err
892		}
893		if payable < 0 {
894			return 0, 0, errPayableOutOfRange
895		}
896		return net, payable, nil
897	}
