186	func parsePrice(text string) (int64, error) {
187		text = strings.TrimSpace(text)
188		price, err := strconv.ParseInt(text, 10, 64)
189		if err != nil {
190			return 0, fmt.Errorf("单价 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
191		}
192		if price < 0 {
193			return 0, fmt.Errorf("单价必须是非负整数分，收到 %d", price)
194		}
195		return price, nil
196	}
