515	func sortByInstant(us []*usageRecord) {
516		// 入参时间均已在载入/导入时校验为 RFC3339。
517		sort.Slice(us, func(i, j int) bool {
518			ti, _ := time.Parse(time.RFC3339, us[i].Time)
519			tj, _ := time.Parse(time.RFC3339, us[j].Time)
520			ui, uj := ti.UTC(), tj.UTC()
521			if !ui.Equal(uj) {
522				return ui.Before(uj)
523			}
524			return us[i].ID < us[j].ID
525		})
526	}
