686	// parseAmount 解析调整金额：有符号 64 位整数、非零（正数补收、负数减免）。
687	func parseAmount(text string) (int64, error) {
688		text = strings.TrimSpace(text)
689		amount, err := strconv.ParseInt(text, 10, 64)
690		if err != nil {
691			return 0, fmt.Errorf("调整金额 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
692		}
693		if amount == 0 {
694			return 0, fmt.Errorf("调整金额不能为零分（正数补收、负数减免）")
695		}
696		return amount, nil
697	}
