699	func cmdBillAdjust(dir, customerID, month, adjID, amountText, reason string) error {
700		if !validMonth(month) {
701			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
702		}
703		if strings.TrimSpace(adjID) == "" {
704			return fmt.Errorf("调整标识不能为空")
705		}
706		amount, err := parseAmount(amountText)
707		if err != nil {
708			return err
709		}
710		if strings.TrimSpace(reason) == "" {
711			return fmt.Errorf("调整原因不能为空")
712		}
713	
714		s, err := loadStore(dir)
715		if err != nil {
716			return err
717		}
718		if _, ok := s.Customers[customerID]; !ok {
719			return fmt.Errorf("客户标识 %q 不存在", customerID)
720		}
721		b, ok := s.Bills[billKey(customerID, month)]
722		if !ok {
723			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），费用调整只能作用于已存在账单", customerID, month)
724		}
725	
726		if existing, ok := s.Adjustments[adjID]; ok {
727			// 相同标识按客户、月份、金额、原因判断重复：内容相同返回已保存
728			// 记录，不再次增减应付；已撤销的重放仍返回已撤销状态，不重新生效。
729			if existing.CustomerID == customerID && existing.Month == month &&
730				existing.Amount == amount && existing.Reason == reason {
731				fmt.Fprintf(stdout, "调整 %q 已存在且内容相同，返回已保存记录（不重复增减应付）：\n\n", adjID)
732				printAdjustment(existing, s)
733				return nil
734			}
735			return fmt.Errorf("调整标识 %q 已存在但内容不同（已有：客户=%s 月份=%s 金额=%d 原因=%q），拒绝复用",
736				adjID, existing.CustomerID, existing.Month, existing.Amount, existing.Reason)
737		}
738	
739		// 应付可行性预检：原总金额 + 全部未撤销调整 + 本次金额必须落在
740		// [0, 有符号 64 位最大值] 内，且不得低于已登记实收，否则拒绝且
741		// 不占用该调整标识。
742		_, payable, err := billTotals(b, adjustmentsFor(s, customerID, month))
743		if err != nil {
744			return fmt.Errorf("账单当前应付异常，拒绝调整: %w", err)
745		}
746		received, err := paymentReceived(s, customerID, month)
747		if err != nil {
748			return fmt.Errorf("实收累计异常，拒绝调整: %w", err)
749		}
750		newPayable, err := addSigned64(payable, amount)
751		if err != nil {
752			return fmt.Errorf("调整后当前应付超出有符号 64 位最大值（当前 %d 分，本次 %+d 分），拒绝调整", payable, amount)
753		}
754		if newPayable < 0 {
755			return fmt.Errorf("调整后当前应付将为 %d 分（小于 0，当前 %d 分，本次 %+d 分），拒绝调整", newPayable, payable, amount)
756		}
757		if newPayable < received {
758			return fmt.Errorf("调整后当前应付 %d 分将低于实收 %d 分（当前 %d 分，本次 %+d 分），拒绝调整；可先撤销误登记的收款再重试",
759				newPayable, received, payable, amount)
760		}
761	
762		a := &adjustment{
763			ID:         adjID,
764			CustomerID: customerID,
765			Month:      month,
766			Amount:     amount,
767			Reason:     reason,
768			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
769		}
770		s.NextSeq++
771		a.Seq = s.NextSeq
772		s.Adjustments[adjID] = a
773	
774		// 调整记录与序号在同一次原子保存中持久化；保存失败则一切不生效，
775		// 该调整标识不被占用。
776		if err := s.save(); err != nil {
777			delete(s.Adjustments, adjID)
778			s.NextSeq--
779			return err
780		}
781		fmt.Fprintf(stdout, "已登记%s调整 %q，客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
782			adjustKind(amount), adjID, customerID, month, newPayable, moneyFen(newPayable))
783		printAdjustment(a, s)
784		return nil
785	}
786	
787	func cmdBillRevoke(dir, adjID, reason string) error {
788		if strings.TrimSpace(adjID) == "" {
789			return fmt.Errorf("调整标识不能为空")
790		}
791		if strings.TrimSpace(reason) == "" {
792			return fmt.Errorf("撤销原因不能为空")
793		}
794	
795		s, err := loadStore(dir)
796		if err != nil {
797			return err
798		}
799		a, ok := s.Adjustments[adjID]
800		if !ok {
801			return fmt.Errorf("调整标识 %q 不存在，无法撤销", adjID)
802		}
803	
804		if a.Revoked {
805			// 相同标识与相同原因重复撤销：幂等成功，不新增记录；
806			// 改用其他原因则拒绝。
807			if a.RevokeReason == reason {
808				fmt.Fprintf(stdout, "调整 %q 已撤销且撤销原因相同，幂等返回（不新增记录）：\n\n", adjID)
809				printAdjustment(a, s)
810				return nil
811			}
812			return fmt.Errorf("调整 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", adjID, a.RevokeReason)
813		}
814	
815		// 撤销只取消该笔调整的金额影响；若撤销后当前应付越界或低于实收则
816		// 拒绝，该调整仍保持有效，可先撤销误登记的收款或在其他合法调整
817		// 改变余额后重试。
818		b := s.Bills[billKey(a.CustomerID, a.Month)] // 载入时已校验存在
819		_, payable, err := billTotals(b, adjustmentsFor(s, a.CustomerID, a.Month))
820		if err != nil {
821			return fmt.Errorf("账单当前应付异常，拒绝撤销: %w", err)
822		}
823		received, err := paymentReceived(s, a.CustomerID, a.Month)
824		if err != nil {
825			return fmt.Errorf("实收累计异常，拒绝撤销: %w", err)
826		}
827		neg, err := neg64(a.Amount)
828		if err != nil {
829			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值，拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试")
830		}
831		newPayable, err := addSigned64(payable, neg)
832		if err != nil {
833			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值（当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
834				payable, a.Amount)
835		}
836		if newPayable < 0 {
837			return fmt.Errorf("撤销后当前应付将为 %d 分（小于 0，当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
838				newPayable, payable, a.Amount)
839		}
840		if newPayable < received {
841			return fmt.Errorf("撤销后当前应付 %d 分将低于实收 %d 分（当前 %d 分，取消 %+d 分），拒绝撤销；可先撤销误登记的收款再重试",
842				newPayable, received, payable, a.Amount)
843		}
844	
845		a.Revoked = true
846		a.RevokeReason = reason
847		a.RevokedAt = time.Now().UTC().Format(time.RFC3339)
848		s.NextSeq++
849		a.RevokeSeq = s.NextSeq
850	
851		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
852		if err := s.save(); err != nil {
853			a.Revoked = false
854			a.RevokeReason = ""
855			a.RevokedAt = ""
856			a.RevokeSeq = 0
857			s.NextSeq--
858			return err
859		}
860		fmt.Fprintf(stdout, "已撤销调整 %q（%s %+d 分），客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
861			adjID, adjustKind(a.Amount), a.Amount, a.CustomerID, a.Month, newPayable, moneyFen(newPayable))
862		printAdjustment(a, s)
863		return nil
864	}
865	
866	// printAdjustment 输出单笔调整记录及其当前状态；payable 取自当前库状态。
867	func printAdjustment(a *adjustment, s *state) {
