883	// parsePositiveAmount 解析收款金额：正整数分（不接受零、负数、小数）。
884	func parsePositiveAmount(text string) (int64, error) {
885		text = strings.TrimSpace(text)
886		amount, err := strconv.ParseInt(text, 10, 64)
887		if err != nil {
888			return 0, fmt.Errorf("收款金额 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
889		}
890		if amount <= 0 {
891			return 0, fmt.Errorf("收款金额必须是正整数分，收到 %d", amount)
892		}
893		return amount, nil
894	}
