899		}
900		amount, err := parsePositiveAmount(amountText)
901		if err != nil {
902			return err
903		}
904		// 单账单收款视为只有一项分配的汇款，与 bill remit 共用同一核心。
905		return registerPayment(dir, customerID, payID, amount, note,
906			[]paymentAllocation{{Month: month, Amount: amount}})
