932	// parseAllocations 解析 <YYYY-MM:金额分> 形式的分配列表：至少一项，
933	// 月份不得重复，每项金额为正整数分。
934	func parseAllocations(args []string) ([]paymentAllocation, error) {
935		if len(args) == 0 {
936			return nil, fmt.Errorf("分配列表不能为空，至少需要一项 <YYYY-MM:金额分>")
937		}
938		seen := make(map[string]bool)
939		allocs := make([]paymentAllocation, 0, len(args))
940		for _, arg := range args {
941			parts := strings.Split(arg, ":")
942			if len(parts) != 2 {
943				return nil, fmt.Errorf("分配项 %q 格式非法，应为 YYYY-MM:金额分（如 2026-09:500）", arg)
944			}
945			month := strings.TrimSpace(parts[0])
946			if !validMonth(month) {
947				return nil, fmt.Errorf("分配项 %q 的月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", arg, parts[0])
948			}
949			if seen[month] {
950				return nil, fmt.Errorf("分配月份 %s 重复，拒绝登记", month)
951			}
952			seen[month] = true
953			amount, err := parsePositiveAmount(parts[1])
954			if err != nil {
955				return nil, fmt.Errorf("分配项 %q 的金额无效: %w", arg, err)
956			}
957			allocs = append(allocs, paymentAllocation{Month: month, Amount: amount})
958		}
959		return allocs, nil
960	}
