1088	func cmdBillUnpay(dir, payID, reason string) error {
1089		if strings.TrimSpace(payID) == "" {
1090			return fmt.Errorf("收款标识不能为空")
1091		}
1092		if strings.TrimSpace(reason) == "" {
1093			return fmt.Errorf("撤销原因不能为空")
1094		}
1095	
1096		s, err := loadStore(dir)
1097		if err != nil {
1098			return err
1099		}
1100		p, ok := s.Payments[payID]
1101		if !ok {
1102			return fmt.Errorf("收款标识 %q 不存在，无法撤销", payID)
1103		}
1104	
1105		if p.Revoked {
1106			// 相同标识与相同原因重复撤销：幂等成功，不新增历史；
1107			// 改用其他原因则拒绝。
1108			if p.RevokeReason == reason {
1109				fmt.Fprintf(stdout, "收款 %q 已撤销且撤销原因相同，幂等返回（不新增历史）：\n\n", payID)
1110				printPayment(p, s)
1111				return nil
1112			}
1113			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", payID, p.RevokeReason)
1114		}
1115	
1116		// 撤销整笔生效：取消该笔在全部分配月份上的最新实收（经更正的以最新
1117		// 分配为准），不接受部分撤销；不改变应付、其他收款或调整，原收款、
1118		// 分配、更正与撤销原因永久保留。
1119		p.Revoked = true
1120		p.RevokeReason = reason
1121		p.RevokedAt = time.Now().UTC().Format(time.RFC3339)
1122		s.NextSeq++
1123		p.RevokeSeq = s.NextSeq
1124	
1125		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
1126		if err := s.save(); err != nil {
1127			p.Revoked = false
1128			p.RevokeReason = ""
1129			p.RevokedAt = ""
1130			p.RevokeSeq = 0
1131			s.NextSeq--
1132			return err
1133		}
1134		fmt.Fprintf(stdout, "已撤销收款 %q（总额 %d 分，%s），取消最新分配：\n", payID, p.Total, moneyFen(p.Total))
1135		printAllocationBalances(s, p, currentAllocations(s, p))
1136		fmt.Fprintln(stdout)
1137		printPayment(p, s)
1138		return nil
1139	}
1140	
1141	// printPayment 输出单笔收款记录：总额、首次登记的全部分配（永久保留，
1142	// 判重依据）与当前状态；经历过更正时同时展示当前生效的最新分配。
1143	// 各月应付/实收取自当前库状态。
1144	func printPayment(p *payment, s *state) {
1145		fmt.Fprintf(stdout, "收款标识：%s\n", p.ID)
1146		fmt.Fprintf(stdout, "客户：%s\n", p.CustomerID)
1147		fmt.Fprintf(stdout, "收款总额：%d 分（%s）\n", p.Total, moneyFen(p.Total))
1148		fmt.Fprintf(stdout, "备注：%s\n", p.Note)
1149		if p.Revoked {
1150			fmt.Fprintf(stdout, "当前状态：已撤销（撤销原因：%s）\n", p.RevokeReason)
1151		} else {
1152			fmt.Fprintf(stdout, "当前状态：实收中\n")
1153		}
1154		fmt.Fprintln(stdout, "分配明细（首次登记，永久保留）：")
1155		for i, al := range p.Allocations {
1156			b := s.Bills[billKey(p.CustomerID, al.Month)] // 载入时已校验存在
1157			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, al.Month))
1158			received, _ := paymentReceived(s, p.CustomerID, al.Month)
1159			fmt.Fprintf(stdout, "  %d. 月份 %s：分配 %d 分（%s）；当前应付 %d 分，实收合计 %d 分，未收余额 %d 分\n",
1160				i+1, al.Month, al.Amount, moneyFen(al.Amount), payable, received, payable-received)
1161		}
1162		if corrs := correctionsFor(s, p.ID); len(corrs) > 0 {
1163			fmt.Fprintf(stdout, "当前分配（经 %d 次更正，以最新为准）：%s\n",
1164				len(corrs), formatAllocations(currentAllocations(s, p)))
1165		}
1166	}
