1168	// --- 收款分配更正 ---
1169	
1170	func cmdBillCorrect(dir, payID, corrID, reason string, allocArgs []string) error {
1171		if strings.TrimSpace(payID) == "" {
1172			return fmt.Errorf("收款标识不能为空")
1173		}
1174		if strings.TrimSpace(corrID) == "" {
1175			return fmt.Errorf("更正标识不能为空")
1176		}
1177		if strings.TrimSpace(reason) == "" {
1178			return fmt.Errorf("更正原因不能为空")
1179		}
1180		allocs, err := parseAllocations(allocArgs)
1181		if err != nil {
1182			return err
1183		}
1184		// 分配顺序不影响更正身份：统一按月份升序保存与比较。
1185		sort.Slice(allocs, func(i, j int) bool { return allocs[i].Month < allocs[j].Month })
1186	
1187		s, err := loadStore(dir)
1188		if err != nil {
1189			return err
1190		}
1191		p, ok := s.Payments[payID]
1192		if !ok {
1193			return fmt.Errorf("收款标识 %q 不存在，无法更正分配", payID)
1194		}
1195	
1196		if existing, ok := s.Corrections[corrID]; ok {
1197			// 相同标识按目标收款、原因与新月份-金额对应关系判重（列表顺序无关）：
1198			// 内容相同返回原更正记录，不改分配、不增历史；后续更正或收款撤销
1199			// 不影响此规则。任何一项不同（含跨收款复用）均拒绝。
1200			if existing.PaymentID == payID && existing.Reason == reason && sameAllocations(existing.Allocations, allocs) {
1201				fmt.Fprintf(stdout, "更正 %q 已存在且内容相同，返回原更正记录（不改分配、不增历史）：\n\n", corrID)
1202				printCorrection(existing, s)
1203				return nil
1204			}
1205			return fmt.Errorf("更正标识 %q 已存在但内容不同（已有：收款=%s 原因=%q 新分配=%s），拒绝复用",
1206				corrID, existing.PaymentID, existing.Reason, formatAllocations(existing.Allocations))
1207		}
1208	
1209		// 新增更正只允许未撤销收款。
1210		if p.Revoked {
1211			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），不能新增分配更正", payID, p.RevokeReason)
1212		}
1213	
1214		// 新分配合计必须等于原收款总额（不重复收钱也不多收），全程整数运算。
1215		var sum int64
1216		for _, al := range allocs {
1217			sum, err = add64(sum, al.Amount)
1218			if err != nil {
1219				return fmt.Errorf("新分配金额合计溢出有符号 64 位整数范围，拒绝更正")
1220			}
1221		}
1222		if sum != p.Total {
1223			return fmt.Errorf("新分配合计 %d 分与原收款 %q 的总额 %d 分不一致，拒绝更正", sum, payID, p.Total)
1224		}
1225		// 新分配月份须是原客户的已结算账单。
1226		for _, al := range allocs {
1227			if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
1228				return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），更正只能分配到已存在账单", p.CustomerID, al.Month)
1229			}
1230		}
1231	
1232		// 以当前最新分配为起点：撤去该笔当前分配再计入新分配后，涉及月份
1233		// 均须满足 0 ≤ 实收 ≤ 应付；其他收款不变，全部合法才整笔生效。
1234		current := currentAllocations(s, p)
1235		for _, m := range unionMonths(current, allocs) {
1236			b := s.Bills[billKey(p.CustomerID, m)] // 载入时已校验存在
1237			_, payable, err := billTotals(b, adjustmentsFor(s, p.CustomerID, m))
1238			if err != nil {
1239				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝更正: %w", p.CustomerID, m, err)
1240			}
1241			received, err := paymentReceived(s, p.CustomerID, m)
1242			if err != nil {
1243				return fmt.Errorf("客户 %s 的 %s 实收累计异常，拒绝更正: %w", p.CustomerID, m, err)
1244			}
1245			// 该笔收款未撤销，其实收必然包含当前分配，撤去不会变负。
1246			received -= allocAmountFor(current, m)
1247			received, err = add64(received, allocAmountFor(allocs, m))
1248			if err != nil {
1249				return fmt.Errorf("客户 %s 的 %s 更正后实收溢出有符号 64 位整数范围，拒绝更正", p.CustomerID, m)
1250			}
1251			if received > payable {
1252				return fmt.Errorf("更正后客户 %s 的 %s 实收 %d 分将超过当前应付 %d 分，拒绝更正；全部状态保持不变",
1253					p.CustomerID, m, received, payable)
1254			}
1255		}
1256	
1257		c := &correction{
1258			ID:          corrID,
1259			PaymentID:   payID,
1260			Reason:      reason,
1261			Allocations: allocs,
1262			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1263		}
1264		s.NextSeq++
1265		c.Seq = s.NextSeq
1266		s.Corrections[corrID] = c
1267	
1268		// 更正记录、序号与余额状态在同一次原子保存中持久化；保存失败则
1269		// 一切不生效，该更正标识不被占用。
1270		if err := s.save(); err != nil {
1271			delete(s.Corrections, corrID)
1272			s.NextSeq--
1273			return err
1274		}
1275		fmt.Fprintf(stdout, "已登记收款分配更正 %q（关联收款 %q）：\n\n", corrID, payID)
1276		printCorrection(c, s)
1277		return nil
1278	}
1279	
1280	// unionMonths 返回两个分配列表涉及月份的并集，按月份升序。
1281	func unionMonths(a, b []paymentAllocation) []string {
1282		set := make(map[string]bool, len(a)+len(b))
1283		for _, al := range a {
1284			set[al.Month] = true
1285		}
1286		for _, al := range b {
1287			set[al.Month] = true
1288		}
1289		months := make([]string, 0, len(set))
1290		for m := range set {
1291			months = append(months, m)
1292		}
1293		sort.Strings(months)
1294		return months
1295	}
1296	
1297	// allocationBefore 返回一次更正发生前该收款生效的分配：上一条更正的
1298	// 新分配，或（首次更正时）收款的原始分配。
1299	func allocationBefore(s *state, c *correction) []paymentAllocation {
1300		before := s.Payments[c.PaymentID].Allocations // 载入时已校验存在
1301		var latest *correction
1302		for _, o := range s.Corrections {
1303			if o.PaymentID == c.PaymentID && o.Seq < c.Seq && (latest == nil || o.Seq > latest.Seq) {
1304				latest = o
1305			}
1306		}
1307		if latest != nil {
1308			before = latest.Allocations
1309		}
1310		return before
1311	}
1312	
1313	// printCorrection 输出单笔更正记录：关联收款、标识、原因、完整前后分配，
1314	// 以及前后分配涉及月份的当前余额。
1315	func printCorrection(c *correction, s *state) {
1316		p := s.Payments[c.PaymentID] // 载入时已校验存在
1317		before := allocationBefore(s, c)
1318		fmt.Fprintf(stdout, "更正标识：%s\n", c.ID)
1319		fmt.Fprintf(stdout, "关联收款：%s（客户 %s，总额 %d 分（%s），备注：%s）\n",
1320			p.ID, p.CustomerID, p.Total, moneyFen(p.Total), p.Note)
1321		fmt.Fprintf(stdout, "原因：%s\n", c.Reason)
1322		fmt.Fprintf(stdout, "更正前分配：%s\n", formatAllocations(before))
1323		fmt.Fprintf(stdout, "更正后分配：%s\n", formatAllocations(c.Allocations))
1324		fmt.Fprintln(stdout, "涉及月份当前余额：")
1325		for _, m := range unionMonths(before, c.Allocations) {
1326			b := s.Bills[billKey(p.CustomerID, m)] // 载入时已校验存在
1327			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, m))
1328			received, _ := paymentReceived(s, p.CustomerID, m)
1329			fmt.Fprintf(stdout, "  月份 %s：本笔分配 %d 分 → %d 分；当前应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1330				m, allocAmountFor(before, m), allocAmountFor(c.Allocations, m),
1331				payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1332		}
1333	}
1334	
1335	// --- 账后对账流水 ---
1336	
1337	// ledgerEvent 是某张已结算账单账后流水中的一个事件：调整、撤销调整、收款、
1338	// 分配更正或撤销收款。事件按全局操作序号升序回放；撤销在其发生序号抵消
1339	// 对应原操作，已撤销记录在撤销之前仍计入，不按当前撤销状态删除原事件；
1340	// 更正在其发生序号把关联收款在本账单的分配由前值替换为后值。
1341	type ledgerEvent struct {
1342		seq           int64  // 全局操作序号（调整/收款/更正及其撤销共用）
1343		kind          string // 事件类型：调整 / 撤销调整 / 收款 / 更正 / 撤销收款
1344		refID         string // 原记录标识（调整标识、收款标识或更正标识）
1345		deltaPayable  int64  // 对当前应付的影响（分，带符号）
1346		deltaReceived int64  // 对实收的影响（分，带符号）
1347		note          string // 原因（调整/更正类）或备注（收款类）
1348		linkSeq       int64  // 撤销事件关联的原操作序号；非撤销事件为 0
1349		payTotal      int64  // 收款类事件：汇款总额
1350		payAlloc      int64  // 收款类事件：本账单分配（撤销收款事件为被取消的最新分配）
1351		payID         string // 更正事件：关联收款标识
1352		beforeAlloc   int64  // 更正事件：本账单更正前分配
1353		afterAlloc    int64  // 更正事件：本账单更正后分配
1354		afterPayable  int64  // 事件后的应付（回放时填充）
1355		afterReceived int64  // 事件后的实收（回放时填充）
1356	}
1357	
1358	// billLedger 把目标账单的调整、调整撤销、收款、分配更正与收款撤销合并为
1359	// 一条按操作序号升序的流水，并以原总金额为初始应付、零实收为起点逐步回放，
1360	// 填充每个事件之后的三项余额。回放覆盖完整流水（不受查询截止序号限制）：
1361	// 序号重复、撤销先于原操作，或任一事件之后不满足 0 ≤ 实收 ≤ 应付 ≤ 有符号
1362	// 64 位最大值，都视为数据异常并拒绝——只检查最终余额会放过中间越界的存档。
1363	// 只读：不修改库、不占用序号、不新增记录。
1364	func billLedger(s *state, b *bill) ([]ledgerEvent, error) {
1365		var events []ledgerEvent
1366		for _, a := range s.Adjustments {
1367			if a.CustomerID != b.CustomerID || a.Month != b.Month {
1368				continue
1369			}
1370			events = append(events, ledgerEvent{
1371				seq: a.Seq, kind: "调整", refID: a.ID,
1372				deltaPayable: a.Amount, note: a.Reason,
1373			})
1374			if a.Revoked {
1375				neg, err := neg64(a.Amount)
1376				if err != nil {
1377					return nil, fmt.Errorf("调整 %q 的金额 %d 分无法抵消（越界），数据异常，拒绝输出流水", a.ID, a.Amount)
1378				}
1379				events = append(events, ledgerEvent{
1380					seq: a.RevokeSeq, kind: "撤销调整", refID: a.ID,
1381					deltaPayable: neg, note: a.RevokeReason, linkSeq: a.Seq,
1382				})
1383			}
1384		}
1385		for _, p := range s.Payments {
1386			if p.CustomerID != b.CustomerID {
1387				continue
1388			}
1389			// 多月汇款只以本账单分配改变实收；更正在其发生序号把本账单分配
1390			// 由前值替换为后值；整笔撤销在同一序号取消撤销时的最新分配。
1391			// 首次登记或任一次更正涉及本账单的，该收款的后续事件都纳入流水。
1392			alloc := p.amountFor(b.Month)
1393			corrs := correctionsFor(s, p.ID)
1394			involved := alloc > 0
1395			if !involved {
1396				for _, c := range corrs {
1397					if allocAmountFor(c.Allocations, b.Month) > 0 {
1398						involved = true
1399						break
1400					}
1401				}
1402			}
1403			if !involved {
1404				continue
1405			}
1406			if alloc > 0 {
1407				events = append(events, ledgerEvent{
1408					seq: p.Seq, kind: "收款", refID: p.ID,
1409					deltaReceived: alloc, note: p.Note,
1410					payTotal: p.Total, payAlloc: alloc,
1411				})
1412			}
1413			running := alloc
1414			for _, c := range corrs {
1415				after := allocAmountFor(c.Allocations, b.Month)
1416				if running == 0 && after == 0 {
1417					continue // 本次更正不涉及本账单
1418				}
1419				events = append(events, ledgerEvent{
1420					seq: c.Seq, kind: "更正", refID: c.ID,
1421					deltaReceived: after - running, note: c.Reason,
1422					payID: p.ID, beforeAlloc: running, afterAlloc: after,
1423				})
1424				running = after
1425			}
1426			if p.Revoked {
1427				events = append(events, ledgerEvent{
1428					seq: p.RevokeSeq, kind: "撤销收款", refID: p.ID,
1429					deltaReceived: -running, note: p.RevokeReason, linkSeq: p.Seq,
1430					payTotal: p.Total, payAlloc: running,
1431				})
1432			}
1433		}
1434		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
1435	
1436		// 逐步回放并核验：只把每个事件的金额影响加到运行余额上，不对发生额
1437		// 做累计求和，因此累计补收/收款发生额超过 64 位上限但每步余额合法时
1438		// 仍能成功。
1439		payable := b.TotalFee
1440		var received int64
1441		seen := make(map[int64]string, len(events))
1442		for i := range events {
1443			ev := &events[i]
1444			desc := ev.kind + " " + ev.refID
1445			if prev, dup := seen[ev.seq]; dup {
1446				return nil, fmt.Errorf("流水序号 %d 重复（%s 与 %s），数据异常，拒绝输出流水", ev.seq, prev, desc)
1447			}
1448			seen[ev.seq] = desc
1449			if ev.linkSeq != 0 && ev.linkSeq >= ev.seq {
1450				return nil, fmt.Errorf("%s 的撤销序号 %d 不晚于原操作序号 %d，数据异常，拒绝输出流水", desc, ev.seq, ev.linkSeq)
1451			}
1452			var err error
1453			if payable, err = addSigned64(payable, ev.deltaPayable); err != nil {
1454				return nil, fmt.Errorf("序号 %d（%s）之后应付越出有符号 64 位整数范围，数据异常，拒绝输出流水", ev.seq, desc)
1455			}
1456			if received, err = addSigned64(received, ev.deltaReceived); err != nil {
1457				return nil, fmt.Errorf("序号 %d（%s）之后实收越出有符号 64 位整数范围，数据异常，拒绝输出流水", ev.seq, desc)
1458			}
1459			if payable < 0 {
1460				return nil, fmt.Errorf("序号 %d（%s）之后应付为 %d 分（小于 0），数据异常，拒绝输出流水", ev.seq, desc, payable)
1461			}
1462			if received < 0 {
1463				return nil, fmt.Errorf("序号 %d（%s）之后实收为 %d 分（小于 0），数据异常，拒绝输出流水", ev.seq, desc, received)
1464			}
1465			if received > payable {
1466				return nil, fmt.Errorf("序号 %d（%s）之后实收 %d 分超过应付 %d 分，数据异常，拒绝输出流水", ev.seq, desc, received, payable)
1467			}
1468			ev.afterPayable = payable
1469			ev.afterReceived = received
1470		}
1471		return events, nil
1472	}
1473	
1474	func cmdBillLedger(dir, customerID, month, cutoffText string, hasCutoff bool) error {
1475		if !validMonth(month) {
1476			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
1477		}
1478		s, err := loadStore(dir)
1479		if err != nil {
1480			return err
1481		}
1482		cust, ok := s.Customers[customerID]
1483		if !ok {
1484			return fmt.Errorf("客户标识 %q 不存在", customerID)
1485		}
1486		b, ok := s.Bills[billKey(customerID, month)]
1487		if !ok {
1488			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算）", customerID, month)
1489		}
1490	
1491		// 截止序号使用调整/收款及其撤销共用的已保存全局序号：省略表示最新，
1492		// 0 只返回初始余额，截止包含该序号；因其他客户或月份操作造成的序号
1493		// 空档合法。负数、非整数或超过存档全局序号上限一律拒绝。
1494		cutoff := s.NextSeq
1495		cutoffDesc := "省略，按最新"
1496		if hasCutoff {
1497			v, perr := strconv.ParseInt(strings.TrimSpace(cutoffText), 10, 64)
1498			if perr != nil {
1499				return fmt.Errorf("截止操作序号 %q 不是非负整数: %w", cutoffText, perr)
1500			}
1501			if v < 0 {
1502				return fmt.Errorf("截止操作序号不能为负数，收到 %d", v)
1503			}
1504			if v > s.NextSeq {
1505				return fmt.Errorf("截止操作序号 %d 超过存档全局序号上限 %d", v, s.NextSeq)
1506			}
1507			cutoff = v
1508			cutoffDesc = "指定"
1509		}
1510	
1511		// 先核验目标账单的完整流水：任何异常（即使发生在截止序号之后）都
1512		// 拒绝，不输出部分正常的报告。
1513		events, err := billLedger(s, b)
1514		if err != nil {
1515			return err
1516		}
1517		printBillLedger(b, cust, s.NextSeq, cutoff, cutoffDesc, events)
1518		return nil
1519	}
1520	
1521	func printBillLedger(b *bill, cust *customer, nextSeq, cutoff int64, cutoffDesc string, events []ledgerEvent) {
1522		fmt.Fprintf(stdout, "账单标识：%s\n", b.ID)
1523		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
1524		fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", b.Month)
1525		fmt.Fprintf(stdout, "原总金额：%d 分（%s）\n", b.TotalFee, moneyFen(b.TotalFee))
1526		fmt.Fprintf(stdout, "存档全局序号上限：%d\n", nextSeq)
1527		fmt.Fprintf(stdout, "截止操作序号：%d（%s）\n", cutoff, cutoffDesc)
1528		fmt.Fprintf(stdout, "初始余额：应付 %d 分（%s），实收 0 分（%s），未收余额 %d 分（%s）\n",
1529			b.TotalFee, moneyFen(b.TotalFee), moneyFen(0), b.TotalFee, moneyFen(b.TotalFee))
1530	
1531		// 截止包含该序号；截止之后的事件（含撤销）既不出现也不影响历史余额。
1532		payable, received := b.TotalFee, int64(0)
1533		var shown []ledgerEvent
1534		for _, ev := range events {
1535			if ev.seq > cutoff {
1536				continue
1537			}
1538			shown = append(shown, ev)
1539			payable, received = ev.afterPayable, ev.afterReceived
1540		}
1541		if len(shown) == 0 {
1542			fmt.Fprintln(stdout, "流水：无（截止序号以内该账单无账后事件）")
1543		} else {
1544			fmt.Fprintln(stdout, "流水（按操作序号升序）：")
1545			for i, ev := range shown {
1546				fmt.Fprintf(stdout, "  %d. %s\n", i+1, formatLedgerEvent(ev))
1547			}
1548		}
1549		fmt.Fprintf(stdout, "截止时余额：应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1550			payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1551	}
1552	
1553	// formatLedgerEvent 渲染一条流水事件：序号、类型、原记录标识、金额影响、
1554	// 原因或备注、撤销关联，以及事件后的应付、实收、未收余额；收款类事件同时
1555	// 说明汇款总额与本账单分配。
1556	func formatLedgerEvent(ev ledgerEvent) string {
1557		after := fmt.Sprintf("事后：应付 %d 分，实收 %d 分，未收余额 %d 分",
1558			ev.afterPayable, ev.afterReceived, ev.afterPayable-ev.afterReceived)
1559		switch ev.kind {
1560		case "调整":
1561			return fmt.Sprintf("序号 %d 调整 %s：应付 %+d 分（%s，%s），原因：%s → %s",
1562				ev.seq, ev.refID, ev.deltaPayable, moneyFen(ev.deltaPayable), adjustKind(ev.deltaPayable), ev.note, after)
1563		case "撤销调整":
1564			return fmt.Sprintf("序号 %d 撤销调整 %s：应付 %+d 分（%s，关联序号 %d 的调整 %s），原因：%s → %s",
1565				ev.seq, ev.refID, ev.deltaPayable, moneyFen(ev.deltaPayable), ev.linkSeq, ev.refID, ev.note, after)
1566		case "收款":
1567			return fmt.Sprintf("序号 %d 收款 %s：实收 %+d 分（%s，汇款总额 %d 分，本账单分配 %d 分），备注：%s → %s",
1568				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payTotal, ev.payAlloc, ev.note, after)
1569		case "更正":
1570			return fmt.Sprintf("序号 %d 更正 %s：实收 %+d 分（%s，关联收款 %s，本账单分配 %d 分 → %d 分），原因：%s → %s",
1571				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payID, ev.beforeAlloc, ev.afterAlloc, ev.note, after)
1572		default: // 撤销收款
1573			return fmt.Sprintf("序号 %d 撤销收款 %s：实收 %+d 分（%s，关联序号 %d 的收款 %s，汇款总额 %d 分，取消本账单分配 %d 分），原因：%s → %s",
1574				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.linkSeq, ev.refID, ev.payTotal, ev.payAlloc, ev.note, after)
1575		}
1576	}
